steps.action:
curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "{
      issues(first: 20, filter: {title: {contains: \"Checkout crash on Safari\"}}) {
        nodes {
          id
          identifier
          title
          estimate
        }
      }
      users(first: 50) {
        nodes {
          id
          name
          email
        }
      }
    }"
  }'
